source(file.path(commandArgs(TRUE)[1],'code/common.R'));f<-file.path(root,'tables/reference_expanded_panel.tsv');if(file.exists(f))quit(save='no');map<-fread(file.path(root,'UC_SCC/gene_mapping.tsv'));genes<-c('KRT14','KRT6A','KRT6B','KRT17','KRT5','COL17A1','EPCAM','KRT7','KRT19','UPK2','COL1A1','COL1A2','DCN','LUM');z<-list();for(route in c('blca','hpca')){t<-readRDS(file.path(prev,'reference',paste0(route,'_trained.rds')));for(g in genes){id<-if(route=='blca')map[symbol==g,feature_id] else g;z[[paste(route,g)]]<-data.table(reference=route,symbol=g,query_ID=paste(id,collapse=';'),present_in_test_genes=any(id%in%t$options$test.genes),selected_model_marker=any(id%in%t$markers$unique))}};fwrite(rbindlist(z),f,sep='\t')
y<-readRDS(file.path(major,'reference/reference.rds'));stopifnot(ncol(y)==44896);q<-LayerData(y,assay='RNA',layer='data');cc<-LayerData(y,assay='RNA',layer='counts');z<-list();for(g in genes){id<-intersect(map[symbol==g,feature_id],rownames(q));for(k in sort(unique(y$major))){ii<-which(y$major==k);z[[paste(g,k)]]<-data.table(symbol=g,major=k,n_reference=length(ii),present=length(id)>0,mean_log=if(length(id))mean(q[id,ii,drop=FALSE]) else NA_real_,pct_positive=if(length(id))mean(colSums(cc[id,ii,drop=FALSE])>0) else NA_real_)}};fwrite(rbindlist(z),file.path(root,'tables/BLCA_reference_expanded_expression.tsv'),sep='\t');cat('REFERENCE_PANEL_CHECK_COMPLETE\n')
